91	  log.section(`Seeding ${ENTRIES.length} uiCopy entries → environment: ${TARGET}`);
92	
93	  // Fetch all existing uiCopy entries across pages before duplicate checks.
94	  // contentful-management paginates at 1,000 — a single request may miss entries.
95	  const existing = [];
96	  let skip = 0;
97	  let total = Infinity;
98	  while (existing.length < total) {
99	    const page = await client.entry.getMany({
100	      environmentId: TARGET,
101	      query: { content_type: 'uiCopy', limit: 1000, skip },
102	    });
103	    total = page.total;
104	    existing.push(...page.items);
105	    skip += page.items.length;
106	    if (page.items.length === 0) break; // guard against a zero-item page to prevent infinite loop
107	  }
108	
109	  // Map from uiCopy key → full entry object so we can inspect sys.publishedVersion below.
110	  const existingEntryMap = new Map(
111	    existing
112	      .map((e) => [e.fields?.key?.['en'], e])
113	      .filter(([key]) => Boolean(key)),
114	  );
115	
116	  let created = 0;
117	  let skipped = 0;
118	  let published = 0;
119	
120	  for (const entry of ENTRIES) {
121	    const existingEntry = existingEntryMap.get(entry.key);
122	    if (existingEntry) {
123	      if (existingEntry.sys.publishedVersion == null) {
124	        // Entry exists as a draft — publish it now so it is available to the app.
125	        await client.entry.publish(
126	          { environmentId: TARGET, entryId: existingEntry.sys.id },
127	          { sys: existingEntry.sys },
128	        );
129	        log.success(`${entry.key} — draft published`);
130	        published++;
131	      } else {
132	        log.skip(`${entry.key} — already published, skipping`);
133	        skipped++;
134	      }
135	      continue;
136	    }
137	
138	    const created_entry = await client.entry.create(
139	      { environmentId: TARGET, contentTypeId: 'uiCopy' },
140	      {
141	        fields: {
142	          title: { 'en': entry.title },
143	          key: { 'en': entry.key },
144	          value: { 'en': entry.value },
145	          description: { 'en': entry.description },
146	        },
147	      },
148	    );
149	
150	    await client.entry.publish(
151	      { environmentId: TARGET, entryId: created_entry.sys.id },
152	      { sys: created_entry.sys },
153	    );
154	
155	    log.success(`${entry.key}`);
156	    created++;
157	  }
158	
159	  log.section('Done');
160	  log.info(`Created and published: ${created}`);
161	  if (published) log.info(`Draft entries published: ${published}`);
162	  if (skipped) log.info(`Skipped (already published): ${skipped}`);
163	}
